// NevNew macOS tool: list_reminders (issue #2)
// Runs one subcommand of n8n/macos_tools.applescript on the host.
const { execFile } = require('child_process');

const SCRIPT = '/Volumes/Ugreen_WD 1.0 TB/grit/nevnew/n8n/macos_tools.applescript';
const SUBCOMMAND = "list_reminders";
const ARGS = []; // [ [slotName, type, description], ... ]

return await (async function () {
  const argv = [SUBCOMMAND];
  for (const [name, type, desc] of ARGS) {
    let v = '';
    try {
      v = $fromAI(name, desc, type);
    } catch (e) {
      v = '';
    }
    v = v === undefined || v === null ? '' : String(v).trim();
    // AppleScript router treats "-" as "no value" for optional slots.
    if (v === '') v = '-';
    argv.push(v);
  }
  return await new Promise((resolve) => {
    execFile(
      '/usr/bin/osascript',
      [SCRIPT, ...argv],
      { timeout: 25000, maxBuffer: 1024 * 1024, encoding: 'utf8' },
      (err, stdout) => {
        const out = String(stdout || '').trim();
        if (out) return resolve(out);
        if (err) return resolve('ERROR: ' + (err.message || 'osascript failed').slice(0, 500));
        resolve('OK (no output)');
      }
    );
  });
})();

