const GH_TOOL = '/Volumes/Ugreen_WD 1.0 TB/grit/nevnew/scripts/gh_tool.sh';
const SUBCOMMAND = "issues_list";
const ARGS = [["state", "string", "open, closed, or all (default open)"], ["limit", "string", "Max results, 1-30 (default 10)"]]; // [ [slotName, type, description], ... ]

return await (async function () {
  const argv = [SUBCOMMAND];
  for (const [name, type, desc] of ARGS) {
    let v = '';
    try {
      v = $fromAI(name, desc, type);
    } catch (e) {
      v = '';
    }
    v = v === undefined || v === null ? '' : String(v).trim();
    if (v !== '') argv.push(v);
  }
  return await new Promise((resolve) => {
    execFile(
      '/bin/bash',
      [GH_TOOL, ...argv],
      { timeout: 28000, maxBuffer: 1024 * 1024, encoding: 'utf8' },
      (err, stdout, stderr) => {
        const out = String(stdout || '').trim();
        if (out) return resolve(out.slice(0, 12000));
        const errText = String(stderr || err && err.message || '').trim();
        resolve('ERROR: ' + (errText || 'gh_tool.sh produced no output').slice(0, 800));
      }
    );
  });
})();

